import{z as B,x as A,o as E,c as p,q as r,j as l,D as i,d as t,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"收缩与实证贝叶斯","description":"","frontmatter":{"title":"收缩与实证贝叶斯","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/shrinkage-empirical-bayes.md","filePath":"quant/shrinkage-empirical-bayes.md","lastUpdated":1791413859000}'),h={name:"quant/shrinkage-empirical-bayes.md"};function d(b,a,m,c,u,_){const n=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=r('<h1 id="收缩与实证贝叶斯" tabindex="-1">收缩与实证贝叶斯 <a class="header-anchor" href="#收缩与实证贝叶斯" aria-label="Permalink to &quot;收缩与实证贝叶斯&quot;">​</a></h1><div class="epigraph"><p>把许多平行的均值各自用样本均值去估，总风险可以高于把它们一起拉向共同中心；经验贝叶斯用数据估这个中心与拉近的强度。</p><footer>—— Stein, Inadmissibility of the Usual Estimator for the Mean of a Multivariate Normal Distribution, 1956；金融里 beta 收缩见 Vasicek, Journal of Finance, 1973</footer></div><p><a href="/quant/bayesian-factor-comparison">上一课</a>用边缘似然比较整套因子模型，惩罚只拟合样本 \\(\\alpha\\) 的额外因子。实践里更常面对的是两千个 \\(\\beta_i\\)、两千个 \\(\\alpha_i\\)，每个都噪声很大。Stein 证明 \\(N\\ge 3\\) 时各维样本均值作为联合估计不可容许；Vasicek 把同一思想用在 \\(\\beta\\)。本课缺口：从模型胜负落到单个参数的收缩。<a href="/quant/cov-shrinkage">协方差收缩</a> 已处理 \\(\\Sigma\\)；这里对象是回归系数、alpha、均值。不重写边缘似然与因子夏普约化。下一课处理收缩仍吃不消的离群点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>观测 \\(y_i=\\theta_i+\\varepsilon_i\\)，\\(\\theta_i\\) 来自超总体。样本 \\(\\hat\\theta_i\\) 对单个 \\(i\\) 无偏，但对损失 \\(\\sum(\\hat\\theta_i-\\theta_i)^2\\) 过大：极端 \\(\\hat\\theta\\) 多半是噪声。收缩</p> \\[\\tilde\\theta_i=(1-w)\\hat\\theta_i+w\\bar\\theta \\]<p>引入偏差、降低方差。经验贝叶斯用截面估 \\(w\\)（噪声方差 vs 真离散）。问题是选收缩目标（总均值、行业均值、CAPM \\(\\beta=1\\)）以及承认异质噪声（薄股票 \\(w\\) 更大）。</p><p><span class="marginnote">直觉类比：一位平时成绩平平的学生某次突然考了 95 分，更可能是运气好而非水平突变；把他的分数往班级平均拉一点，预测下次考试反而更准。极端样本值往往掺着噪声，收缩就是把这部分噪声还回去。</span></p><p>资产定价里：Vasicek \\(\\beta\\) 是默认；\\(\\alpha\\) 收缩决定「有没有特异收益可做」；均值收缩是 Black–Litterman 与组合的入口。对象不是再比较模型后验，而是给出可用于下游的点。</p><h3 id="与惩罚回归的关系" tabindex="-1">与惩罚回归的关系 <a class="header-anchor" href="#与惩罚回归的关系" aria-label="Permalink to &quot;与惩罚回归的关系&quot;">​</a></h3><p>岭回归、<a href="/quant/regularized-linear-alpha">正则化线性 alpha</a> 是同一偏差–方差的计算形式。经验贝叶斯给 \\(w\\) 一个分层概率解释，并允许从数据估超参。LASSO 做选择（点质量在零），James–Stein 做均匀拉近。因子载荷多、且你相信多数真 \\(\\alpha\\) 接近零时，选择式先验（spike-and-slab）更接近上一课的包含概率。</p><p><span class="marginnote">收缩不是「把 t 不显著的变成零」的事后手续。先看 t 再收缩，用了两次数据，覆盖概率坏。应预先声明目标与公式，或用分层模型一次算出后验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>Vasicek \\(\\beta\\)。</strong> 先验 \\(\\beta\\sim N(\\beta_0,v_0)\\)，似然方差来自时间序列。后验均值是精度加权。\\(\\beta_0\\) 常用 1 或行业均值；\\(v_0\\) 用截面残差减平均估计方差（经验贝叶斯）。薄股票、短窗，权重大幅向 \\(\\beta_0\\)。</p><p><span class="marginnote">数字实例：某股用 60 个月估 \\(\\beta\\)，时间序列标准误约 0.3；若全市场 \\(\\beta\\) 的截面标准差也是 0.3，则拉向先验的权重约 \\(0.09/(0.09+0.09)=0.5\\)，后验取样本值与先验各一半。若只有 24 个月、标准误升到 0.5，权重变成约 \\(0.25/(0.25+0.09)\\approx0.74\\)，估计被大幅拉向目标。</span></p><p><strong>alpha / 均值。</strong> 把 \\(\\hat\\alpha_i\\) 向 0 或向截面均值拉。若目标是组合，向零收缩 \\(\\alpha\\) 等于缩小主动权重。Efron–Morris 给出经验贝叶斯的经典实现。注意：\\(\\hat\\alpha\\) 相关（共同因子残差），独立正态公式会收缩不够或过度；应先滤因子，或对残差用多元分层。</p><p><strong>协方差。</strong> Ledoit–Wolf 向单位阵或常相关目标拉，见已有课。本课不重复特征值公式，只强调：均值与 \\(\\beta\\) 的收缩不能代替 \\(\\Sigma\\) 收缩，优化器两头都噪。</p><h3 id="超参不要样本内调到最大夏普" tabindex="-1">超参不要样本内调到最大夏普 <a class="header-anchor" href="#超参不要样本内调到最大夏普" aria-label="Permalink to &quot;超参不要样本内调到最大夏普&quot;">​</a></h3><p>用同一段收益既估 \\(w\\) 又评组合，会挑出过小的 \\(w\\)（看起来主动很强）。应时间序列交叉验证估超参，或用封闭的经验贝叶斯矩（不直接瞄夏普）。这与预测回归的样本外纪律相同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>平方损失下，后验均值是最优点估计。经验贝叶斯用边际分布估先验方差：截面看到的离散 = 真异质 + 估计噪声，减去噪声得到 \\(v_0\\)，再得 \\(w\\)。机制是<strong>借强度</strong>：每个 \\(i\\) 用其他 \\(j\\) 的信息。Stein 的不可容许是联合损失下的定理；对单个预先指定的 \\(i\\)，无偏 \\(\\hat\\theta_i\\) 仍可更可取——所以对「这一只股票的 \\(\\beta\\) 要不要收缩」取决于你的损失是组合级还是个案级。</p>',21)),(E(),l(o,null,{default:i(()=>[s(n,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%88%AA%E9%9D%A2%E7%9C%8B%E5%88%B0%E7%9A%84%E7%A6%BB%E6%95%A3%20Var(%CE%B8%CC%82)%22%5D%20--%3E%20EQ%5B%22%E7%AD%89%E4%BA%8E%20%E7%9C%9F%E5%BC%82%E8%B4%A8%20%E5%8A%A0%20%E5%B9%B3%E5%9D%87%E4%BC%B0%E8%AE%A1%E5%99%AA%E5%A3%B0%22%5D%0A%20%20EQ%20--%3E%20SUB%5B%22%E5%87%8F%E5%8E%BB%E5%99%AA%E5%A3%B0%E9%83%A8%E5%88%86%20%E2%86%92%20%E5%85%88%E9%AA%8C%E6%96%B9%E5%B7%AE%20v0%22%5D%0A%20%20SUB%20--%3E%20W%5B%22%E6%94%B6%E7%BC%A9%E6%9D%83%E9%87%8D%20w%20%3D%20%E5%99%AA%E5%A3%B0%E5%8D%A0%E6%AF%94%22%5D%0A%20%20W%20--%3E%20PULL%5B%22%E5%99%AA%E5%A3%B0%E8%B6%8A%E5%A4%A7%E7%9A%84%20i%20%E8%A2%AB%E6%8B%89%E5%90%91%E7%9B%AE%E6%A0%87%E8%B6%8A%E5%A4%9A%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">常见误区：对只有三五个成员的对象（如少数货币对）也套收缩。借强度的前提是存在一大群可交换的同类参数；成员太少时「超总体」本身几乎测不准，拉向一个噪声很大的均值只会互相污染，不会降总风险。</span></p><p>与 Fama–MacBeth 生成回归量：收缩 \\(\\beta\\) 再进截面，能减轻衰减（attenuation 的反向是噪声 \\(\\beta\\) 把 \\(\\lambda\\) 拉向零）。Vasicek 之后再 FM，是工程上常见的两步；贝叶斯层次可一次完成，但报告更难。</p><p><span class="marginnote">向 1 收缩 \\(\\beta\\)，会让高 \\(\\beta\\) 股票的 \\(\\beta\\) 下来、低的上去，市场中性组合的残差风险下降，但也削弱了「赌 \\(\\beta\\)」的暴露。目标必须与策略一致：做 BAB 不应把 \\(\\beta\\) 全拉到 1。</span></p><h3 id="何时不收缩" tabindex="-1">何时不收缩 <a class="header-anchor" href="#何时不收缩" aria-label="Permalink to &quot;何时不收缩&quot;">​</a></h3><p>\\(N=3\\) 的货币对、明确的结构参数（久期、合约乘数）、以及你要对单一事件做无偏描述（事件 CAR）——收缩会把案例拉向总体，掩盖正是你想看的异常。事件研究的平均 CAR 已经是一种借强度；再把每个 CAR 向零拉，是另一个问题。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>肥尾下正态分层会把危机当成「真 \\(\\theta\\) 极大」，收缩不够；应 t 分层或先 winsor。生存偏差让存活公司的 \\(\\alpha\\) 截面右偏，经验贝叶斯目标被污染。国际样本的超总体是否共同，值得按市场分层。</p><p>工程：个股 \\(\\beta\\) 默认 Vasicek 或行业分层；协方差走 Ledoit–Wolf；\\(\\alpha\\) 收缩超参用样本外。不要对已经 <a href="/quant/ipca">IPCA</a> 结构化的载荷再随便 James–Stein 一层而不声明。不要把收缩后的 \\(t\\)（用未收缩标准误）当推断——标准误须与估计器匹配，或改报后验区间。下一课：离群让均值与 \\(\\beta\\) 的高斯分层一起坏掉。</p>',8)),(E(),l(o,null,{default:i(()=>[s(n,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20HAT%5B%22%E5%90%84%E8%B5%84%E4%BA%A7%20%CE%B8%CC%82_i%20%E5%BE%88%E5%99%AA%22%5D%20--%3E%20EB%5B%22%E7%BB%8F%E9%AA%8C%E8%B4%9D%E5%8F%B6%E6%96%AF%3A%20%E4%BC%B0%E8%B6%85%E6%80%BB%E4%BD%93%22%5D%0A%20%20EB%20--%3E%20W%5B%22%E6%94%B6%E7%BC%A9%E6%9D%83%E9%87%8D%20w%22%5D%0A%20%20TGT%5B%22%E7%9B%AE%E6%A0%87%3A%200%20%2F%201%20%2F%20%E8%A1%8C%E4%B8%9A%E5%9D%87%E5%80%BC%22%5D%20--%3E%20TILDE%5B%22%CE%B8%CC%83_i%20%3D%20(1-w)%CE%B8%CC%82_i%20%2B%20w%20%E7%9B%AE%E6%A0%87%22%5D%0A%20%20W%20--%3E%20TILDE%0A%20%20TILDE%20--%3E%20USE%5B%22%E4%B8%8B%E6%B8%B8%3A%20%E5%AF%B9%E5%86%B2%E3%80%81FM%E3%80%81%E7%BB%84%E5%90%88%22%5D%0A%20%20LOSS%5B%22%E8%81%94%E5%90%88%E5%B9%B3%E6%96%B9%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20STEIN%5B%22Stein%3A%20%E4%B8%8D%E6%94%B6%E7%BC%A9%E4%B8%8D%E5%8F%AF%E5%AE%B9%E8%AE%B8%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"多参数联合损失下，把估计拉向超总体中心，往往优于各估各的样本矩。"),e("li",null,"Vasicek 的 \\(\\beta\\) 收缩是金融默认的经验贝叶斯；权重由估计噪声对真截面离散决定。"),e("li",null,"超参须样本外或用边际矩，不能对同一夏普调 \\(w\\)。"),e("li",null,"收缩改点估计，推断要用匹配的后验或适当标准误；与协方差收缩分工。"),e("li",null,[t("出处：Stein, 1956；James and Stein, 1961；Vasicek, "),e("em",null,"Journal of Finance"),t(", 1973；Efron and Morris 的经验贝叶斯；协方差一侧见 Ledoit and Wolf。")])],-1))])}const C=B(h,[["render",d]]);export{D as __pageData,C as default};
